import XCTest

/// Runs only in the R1XCTest project generated by xcode-r1-acceptance.py.
/// Never launches or terminates the production bundle identifier.
@MainActor
final class NativeAcceptanceTests: XCTestCase {
    private var app: XCUIApplication!

    override func setUpWithError() throws {
        continueAfterFailure = false
        // Use the app path configured by this disposable test target, avoiding
        // Launch Services choosing another build with the same test identity.
        app = XCUIApplication()
        app.launchArguments = ["-AppleLanguages", "(zh-Hans)", "-AppleLocale", "zh_CN",
                               "-welcome.hasBeenShown", "YES", "-welcome.showAtLaunch", "NO"]
        app.launch()
        XCTAssertTrue(app.windows.firstMatch.waitForExistence(timeout: 10))
    }

    override func tearDownWithError() throws {
        app?.terminate()
    }

    func testActualHoverUsesSelectedMetricAndClearsOnExit() throws {
        app.buttons["统计"].click()
        let weekdayIndex = (Calendar.current.component(.weekday, from: Date()) + 5) % 7
        let bucket = app.descendants(matching: .any)["statistics-bucket-\(weekdayIndex)"].firstMatch
        XCTAssertTrue(bucket.waitForExistence(timeout: 5))
        bucket.hover()
        let tooltip = app.staticTexts["statistics-bucket-tooltip"]
        XCTAssertTrue(tooltip.waitForExistence(timeout: 5), "Real pointer entry must show the tooltip")
        attachWindow("hover-count")
        XCTAssertEqual(text(of: tooltip), "2")

        app.buttons["时长"].click()
        bucket.hover()
        XCTAssertTrue(tooltip.waitForExistence(timeout: 5))
        attachWindow("hover-duration")
        XCTAssertEqual(text(of: tooltip), "2 分钟")

        app.buttons["返回计时器"].hover()
        let gone = NSPredicate(format: "exists == false")
        expectation(for: gone, evaluatedWith: tooltip)
        waitForExpectations(timeout: 5)
    }

    func testWindowDragHasCorrectDisplacementAndStableSize() throws {
        let window = app.windows.firstMatch
        app.activate()
        window.coordinate(withNormalizedOffset: CGVector(dx: 0.15, dy: 0.55)).click()
        XCTAssertEqual(window.frame.width, 380, accuracy: 1)
        XCTAssertEqual(window.frame.height, 272, accuracy: 1)
        let original = window.frame
        attachWindow("before-native-drag")
        let start = window.coordinate(withNormalizedOffset: CGVector(dx: 0.15, dy: 0.55))
        let destination = start.withOffset(CGVector(dx: 80, dy: 40))
        start.press(forDuration: 0.1, thenDragTo: destination)
        attachWindow("after-native-drag")
        XCTAssertEqual(window.frame.minX - original.minX, 80, accuracy: 2)
        XCTAssertEqual(window.frame.minY - original.minY, 40, accuracy: 2)
        XCTAssertEqual(window.frame.size.width, original.width, accuracy: 1)
        XCTAssertEqual(window.frame.size.height, original.height, accuracy: 1)
        attachWindow("native-drag")
    }

    private func attachWindow(_ name: String) {
        let attachment = XCTAttachment(screenshot: app.windows.firstMatch.screenshot())
        attachment.name = name
        attachment.lifetime = .keepAlways
        add(attachment)
        let accessibility = XCTAttachment(string: app.windows.firstMatch.debugDescription)
        accessibility.name = name + "-accessibility"
        accessibility.lifetime = .keepAlways
        add(accessibility)
    }

    private func text(of element: XCUIElement) -> String {
        element.label.isEmpty ? (element.value as? String ?? "") : element.label
    }
}
